import { D1QB } from 'workers-qb'

type Schema = {
  employees: {
    id: number
    name: string
    role: string
    level: number
    active: boolean
  }
}

const qb = new D1QB<Schema>(env.DB)

const employeeListModular = await qb
  .select('employees')
  .where('active = ?', true)
  .all()
